package com.coffeeshop.controller;import com.coffeeshop.dto.CustomerCommands;import com.coffeeshop.model.CustomerModels.Customer;import com.coffeeshop.service.CustomerService;import javafx.application.Platform;import javafx.beans.property.SimpleStringProperty;import javafx.fxml.FXML;import javafx.geometry.Insets;import javafx.scene.control.*;import javafx.scene.layout.GridPane;import java.util.*;import java.util.concurrent.CompletableFuture;
public final class CustomerManagementController{private final CustomerService service;@FXML private TextField searchField;@FXML private ChoiceBox<String>activeFilter;@FXML private TableView<Customer>customerTable;@FXML private TableColumn<Customer,String>numberColumn,nameColumn,phoneColumn,emailColumn,businessColumn,activeColumn;@FXML private Label messageLabel;@FXML private Button editButton,activeButton;public CustomerManagementController(CustomerService s){service=Objects.requireNonNull(s);}@FXML private void initialize(){numberColumn.setCellValueFactory(v->text(v.getValue().number()));nameColumn.setCellValueFactory(v->text(v.getValue().displayName()));phoneColumn.setCellValueFactory(v->text(orDash(v.getValue().phone())));emailColumn.setCellValueFactory(v->text(orDash(v.getValue().email())));businessColumn.setCellValueFactory(v->text(orDash(v.getValue().legalName())));activeColumn.setCellValueFactory(v->text(v.getValue().active()?"Active":"Inactive"));activeFilter.getItems().setAll("Active","Inactive","All");activeFilter.setValue("Active");activeFilter.valueProperty().addListener((o,a,b)->refresh());searchField.textProperty().addListener((o,a,b)->refresh());customerTable.getSelectionModel().selectedItemProperty().addListener((o,a,b)->selection(b));refresh();}@FXML private void refresh(){Boolean active="All".equals(activeFilter.getValue())?null:"Active".equals(activeFilter.getValue());CompletableFuture.supplyAsync(()->service.customers(searchField.getText(),active)).whenComplete((v,e)->Platform.runLater(()->{if(e!=null){messageLabel.setText("Unable to load customers.");return;}customerTable.getItems().setAll(v);messageLabel.setText(v.isEmpty()?"No customers match the current filters.":"");selection(customerTable.getSelectionModel().getSelectedItem());}));}@FXML private void add(){editor(null).ifPresent(this::save);}@FXML private void edit(){Customer c=customerTable.getSelectionModel().getSelectedItem();if(c!=null)editor(c).ifPresent(this::save);}@FXML private void toggle(){Customer c=customerTable.getSelectionModel().getSelectedItem();if(c!=null)write(()->service.setActive(c,!c.active()),c.active()?"Customer deactivated.":"Customer activated.");}private void save(CustomerCommands.Save q){write(()->service.save(q),"Customer saved.");}private void write(Runnable r,String ok){CompletableFuture.runAsync(r).whenComplete((v,e)->Platform.runLater(()->{if(e==null){refresh();messageLabel.setText(ok);}else messageLabel.setText(message(e));}));}private Optional<CustomerCommands.Save>editor(Customer c){Dialog<CustomerCommands.Save>d=new Dialog<>();d.setTitle(c==null?"Add customer":"Edit customer");ButtonType save=new ButtonType("Save",ButtonBar.ButtonData.OK_DONE);d.getDialogPane().getButtonTypes().addAll(ButtonType.CANCEL,save);TextField first=f(c==null?null:c.firstName()),last=f(c==null?null:c.lastName()),legal=f(c==null?null:c.legalName()),tax=f(c==null?null:c.taxNumber()),phone=f(c==null?null:c.phone()),email=f(c==null?null:c.email());TextArea notes=new TextArea(c==null||c.notes()==null?"":c.notes());notes.setPrefRowCount(3);CheckBox active=new CheckBox("Active");active.setSelected(c==null||c.active());GridPane p=new GridPane();p.setHgap(12);p.setVgap(8);p.setPadding(new Insets(8));field(p,0,"First name",first);field(p,1,"Last name",last);field(p,2,"Business/legal name",legal);field(p,3,"Tax registration",tax);field(p,4,"Phone",phone);field(p,5,"Email",email);field(p,6,"Notes",notes);p.add(active,1,7);d.getDialogPane().setContent(p);d.getDialogPane().setPrefWidth(520);d.setResultConverter(b->b==save?new CustomerCommands.Save(c==null?null:c.id(),first.getText(),last.getText(),legal.getText(),tax.getText(),phone.getText(),email.getText(),notes.getText(),active.isSelected(),c==null?null:c.rowVersion()):null);return d.showAndWait();}private static TextField f(String s){return new TextField(s==null?"":s);}private static void field(GridPane p,int r,String n,Control c){p.add(new Label(n),0,r);c.setMaxWidth(Double.MAX_VALUE);p.add(c,1,r);}private void selection(Customer c){editButton.setDisable(c==null);activeButton.setDisable(c==null);activeButton.setText(c==null||c.active()?"Deactivate":"Activate");}private static SimpleStringProperty text(String s){return new SimpleStringProperty(s);}private static String orDash(String s){return s==null?"-":s;}private static String message(Throwable e){Throwable x=e;while(x.getCause()!=null)x=x.getCause();return x instanceof IllegalArgumentException||x instanceof IllegalStateException?x.getMessage():"Unable to update the customer.";}}
